const { DateTime } = require('luxon');

const timezone = $input.first().json.businessTimezone || 'America/Chicago';
const now = DateTime.now().setZone(timezone);

const day = now.weekday; // 1 = Monday, 7 = Sunday
const time = now.toFormat('HH:mm');

let insideBusinessHours = false;

if (day >= 1 && day <= 5) {
  insideBusinessHours = time >= '08:00' && time <= '18:00';
}

if (day === 6) {
  insideBusinessHours = time >= '09:00' && time <= '13:00';
}

return $input.all().map(item => ({
  json: {
    ...item.json,
    currentLocalTime: now.toISO(),
    currentDay: day,
    insideBusinessHours
  }
}));

const { DateTime } = require('luxon');

const now = DateTime.now().setZone('America/Chicago');

const category = $input.first().json.category;

let minutes = 240;

if (category === 'Maintenance Request') minutes = 60;
if (category === 'Leasing Enquiry') minutes = 30;
if (category === 'Rent/Payment Issue') minutes = 120;
if (category === 'General Enquiry') minutes = 240;
if (category === 'Unknown') minutes = 240;

return $input.all().map(item => ({
  json: {
    ...item.json,
    slaMinutes: minutes,
    slaDeadline: now.plus({ minutes }).toISO()
  }
}));

